<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/config.php'; require_once dirname(__DIR__,2).'/database/config/db.php'; require_once dirname(__DIR__,2).'/security/ApiErrorResponder.php'; require_once dirname(__DIR__,2).'/security/middleware/AuthMiddleware.php'; require_once dirname(__DIR__,2).'/services/MessageService.php'; require_once dirname(__DIR__,2).'/services/ChannelService.php';
header('Content-Type: application/json'); AuthMiddleware::startSession(); $user=AuthMiddleware::requireAuth(true);
try{$channelId=filter_input(INPUT_GET,'channel_id',FILTER_VALIDATE_INT);if(!$channelId){http_response_code(400);echo json_encode(['error'=>'channel_id is required']);exit;}$before=filter_input(INPUT_GET,'before',FILTER_VALIDATE_INT)?:null;$limit=filter_input(INPUT_GET,'limit',FILTER_VALIDATE_INT)?:50;$pinnedOnly=filter_input(INPUT_GET,'pinned',FILTER_VALIDATE_INT)===1;$db=Database::getInstance();$accessStmt=$db->prepare("SELECT c.is_private,c.created_by,sm.server_role,EXISTS(SELECT 1 FROM channel_members cm WHERE cm.channel_id=c.id AND cm.user_id=:uid_access) AS has_channel_access FROM channels c JOIN server_members sm ON sm.server_id=c.server_id AND sm.user_id=:uid_member WHERE c.id=:cid LIMIT 1");$accessStmt->execute([':uid_access'=>$user['id'],':uid_member'=>$user['id'],':cid'=>$channelId]);$access=$accessStmt->fetch(PDO::FETCH_ASSOC);if(!$access)throw new RuntimeException('Access denied',403);$canManage=in_array($access['server_role'],['owner','admin','moderator'],true)||(int)$access['created_by']===(int)$user['id'];if((int)$access['is_private']===1&&!(bool)$access['has_channel_access']&&!$canManage)throw new RuntimeException('You do not have access to this private channel',403);$service=new MessageService();if($pinnedOnly){echo json_encode(['success'=>true,'messages'=>$service->getPinnedMessages((int)$channelId,$user['id'])]);exit;}$messages=$service->getMessages((int)$channelId,$user['id'],$before,$limit);(new ChannelService())->markRead((int)$channelId,$user['id']);echo json_encode(['success'=>true,'messages'=>$messages,'has_more'=>count($messages)>=$limit]);}
catch(Throwable $e){$code=($e->getCode()>=400&&$e->getCode()<600)?$e->getCode():500;ApiErrorResponder::throwable('chat/get-messages',$e,$code,'Unable to load messages.');}
